import {esc,codeBadge,countLabel,actionText,closeButton,icon} from './shared.js';
import {library} from '../reference-model.js';
import {seasonRules} from '../data/season-policy.js';
export function referenceArticle(f){
  const {studyStyle:style,studyVariant:variant,studyAccessory:accessory}=f;
  return `<article id="formula-reader" tabindex="-1" class="fl-formula fl-study"><header><h2>${esc(f.title)}</h2></header>
  <div class="fl-study-body"><figure class="fl-study-hero"><button type="button" class="fl-image-button" data-study-image="true" aria-label="View larger image: ${esc(variant.title)}"><img src="${variant.src}" alt="${esc(variant.alt)}" width="825" height="1100" fetchpriority="high"><span>AI style idea</span><small>${actionText('View larger','expand')}</small></button></figure>
  <div class="fl-study-controls"><h3>${esc(style.name)}</h3>
  <div class="fl-palette-heading"><span class="eyebrow">COLOR OPTIONS</span><small>${countLabel(style.variants.length,'option')}</small></div>
  <div class="fl-palette-picker" role="group" aria-label="Choose a color option">${style.variants.map(v=>`<button type="button" data-study-palette="${v.id}" aria-pressed="${v.id===variant.id}" title="${esc(v.title)}"><span class="fl-palette-dots" aria-hidden="true">${v.palette.map(([name,hex])=>`<i style="background:${hex}"></i>`).join('')}</span><span>${esc(v.palette.map(([name])=>name).join(' · '))}</span><b aria-hidden="true">${v.id===variant.id?icon('check'):''}</b></button>`).join('')}</div>
  <span class="visually-hidden" aria-live="polite">Current palette: ${esc(variant.title)}</span>
  ${style.accessories?`<details class="fl-accessory-options" ${accessory!=='none'?'open':''}><summary>${style.accessories.some(a=>a.id==='bag')?'Bag options':'Finishing touches'}</summary><div class="fl-accessory-picker" role="group" aria-label="Optional details for this look">${style.accessories.map(a=>`<button type="button" class="btn" data-study-accessory="${a.id}" aria-pressed="${accessory===a.id}">${esc(a.name)}</button>`).join('')}</div></details>`:''}
  <div class="fl-actions"><button type="button" class="btn primary" data-scroll-matches>${actionText('See options from my wardrobe','chevron-down')}</button></div>
  <dl class="fl-wear-tips">${style.tips.map(([label,text])=>`<div><dt>${esc(label)}</dt><dd>${esc(text)}</dd></div>`).join('')}</dl>
  </div></div>
  <details class="fl-reference-drawer"><summary>About this look <span>Colors and styling variations</span></summary><p>${style.evidence?esc(style.evidence):'This look explores colors and styling rather than copying an original outfit item for item.'} The original creator and source link haven’t been verified.</p></details></article>`;
}
export function formulaImageDialog(formula,images,index){const im=images[index];return `<div class="dialog-head"><span class="eyebrow">${im.kind==='ai'?'AI inspiration · Not your wardrobe':'Original inspiration · Screen photo'}</span>${closeButton('formula-image','Close inspiration image')}</div><div class="fl-lightbox"><img src="${im.src}" alt="${esc(im.alt)}"><div>${formula.studyStyle?codeBadge(formula.studyStyle):''}<h2 id="formula-image-title">${esc(im.title)}</h2><p>${esc(im.note)}</p><p class="sources">${im.kind==='ai'?'An AI style idea, not a photo of your clothes or a fit check. Details may differ from real items.':'The original creator and link are unverified. A screen photo may change how colors appear and cannot confirm fabric.'}</p><div class="fl-lightbox-controls"><button type="button" class="btn" data-gallery-step="-1" aria-label="Previous image" ${index===0?'disabled':''}>${icon('chevron-left')}</button><span aria-live="polite">Image ${index+1} of ${images.length}</span><button type="button" class="btn" data-gallery-step="1" aria-label="Next image" ${index===images.length-1?'disabled':''}>${icon('chevron-right')}</button></div></div></div>`;}
export function formulaSources(){return `<div class="dialog-head"><h2 id="source-title">About the images and seasons</h2>${closeButton('formula-sources','Close image and season information')}</div><section class="fl-source"><h3>About the images</h3><p>AI images show color and layering ideas. They aren’t photos of your clothes or a fit check. Confirm fabric, thickness and warmth with the actual items.</p></section><section class="fl-source"><h3>How seasons are labeled</h3><p>Each look appears in one season, using the first matching rule below. These labels help you browse; they aren’t a weather forecast or a guarantee of warmth.</p><ol>${seasonRules.map(([name,rule])=>`<li><b>${name}</b>: ${esc(rule)}</li>`).join('')}</ol></section>${library.sources.map(s=>`<section class="fl-source"><h3>${s.url?`<a href="${s.url}" target="_blank" rel="noreferrer">${esc(s.title)} ${icon('external-link')}<span class="visually-hidden"> (opens in a new tab)</span></a>`:esc(s.title)}</h3><p>${esc(s.text)}</p></section>`).join('')}`;}
